begin
  -- Transport guard: nothing is written unless the embedded plan is byte-identical to the reviewed plan.
  if c2_plan_sha <> '02d2b12071ed72c918c20f92831e4416bc327cf795bfde22be347a49a3dabcfa' then
    raise exception 'C2 refused: embedded plan sha256 % is not the reviewed plan 02d2b12071ed72c918c20f92831e4416bc327cf795bfde22be347a49a3dabcfa', c2_plan_sha using errcode = 'P0001';
  end if;
<<c2_apply>>
declare
b uuid; n int; nb int := 0;
ins_claims int := 0; ins_details int := 0; ins_ents int := 0; ins_adj int := 0; ins_ledger int := 0;
tot_claims int := 0; tot_details int := 0; tot_ents int := 0; tot_ledger int := 0;
rc fat.operational_claims; ec fat.operational_claims;
re fat.claim_entitlements; ee fat.claim_entitlements;
rl fat.migration_source_rows; el fat.migration_source_rows;
rp fat.payment_records; ep fat.payment_records; elk fat.entitlement_payment_links; lk record; ps record;
new_recs uuid[] := '{}'; ch boolean; cur_status text;
ins_pay int := 0; tot_pay int := 0; ins_links int := 0; tot_links int := 0;
ins_ids int := 0; tot_ids int := 0; ins_fys int := 0; tot_fys int := 0; nd int := 0;
pi record; ai fat.app_identities; pf fat.financial_years; ef fat.financial_years;
r_recall_details fat.recall_details; e_recall_details fat.recall_details; r_retain_details fat.retain_details; e_retain_details fat.retain_details; r_standby_details fat.standby_details; e_standby_details fat.standby_details; r_muster_dismiss_details fat.muster_dismiss_details; e_muster_dismiss_details fat.muster_dismiss_details; r_spoilt_meal_details fat.spoilt_meal_details; e_spoilt_meal_details fat.spoilt_meal_details; r_delayed_meal_details fat.delayed_meal_details; e_delayed_meal_details fat.delayed_meal_details;
k text := c2_plan#>>'{batch,batch_key}';
begin
if md5((jsonb_build_object(
'stations', coalesce((select jsonb_agg(jsonb_build_object('id', st.id, 'name', st.name) order by st.id) from fat.stations st
where st.id in (select (jsonb_array_elements_text((c2_plan->'target_scope')->'stations'))::int)), '[]'::jsonb),
'rates', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'code', r.code, 'unit', r.unit) order by r.id) from fat.rates r
where coalesce(((c2_plan->'target_scope')->>'has_source')::boolean, false) and r.code in ('enterprise_base_pay_weekly', 'overtime_rate_factor', 'overtime_hourly_divisor', 'double_time_multiplier', 'single_time_multiplier', 'time_and_half_multiplier', 'travel_per_km', 'meal_allowance', 'spoilt_meal_allowance', 'relieving_allowance')), '[]'::jsonb),
'rate_versions', coalesce((select jsonb_agg(jsonb_build_object('id', v.id, 'rate_id', v.rate_id, 'version_label', v.version_label, 'value', v.value::text,
'effective_from', v.effective_from, 'classification', v.classification, 'source_kind', v.source_kind, 'source_ref', v.source_ref,
'withdrawn', v.withdrawn_at is not null) order by v.id)
from fat.rate_versions v join fat.rates r on r.id = v.rate_id where coalesce(((c2_plan->'target_scope')->>'has_source')::boolean, false) and r.code in ('enterprise_base_pay_weekly', 'overtime_rate_factor', 'overtime_hourly_divisor', 'double_time_multiplier', 'single_time_multiplier', 'time_and_half_multiplier', 'travel_per_km', 'meal_allowance', 'spoilt_meal_allowance', 'relieving_allowance')), '[]'::jsonb),
'native_claims', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'owner_id', c.owner_id, 'claim_type', c.claim_type, 'claim_date', c.claim_date,
'station_id_snapshot', c.station_id_snapshot, 'dest_station_id', coalesce(sd.standby_station_id, md.md_station_id)) order by c.id)
from fat.operational_claims c
left join fat.standby_details sd on sd.claim_id = c.id
left join fat.muster_dismiss_details md on md.claim_id = c.id
where c.prototype_row_id is null and c.migration_batch_id is null
and c.owner_id::text in (select jsonb_array_elements_text((c2_plan->'target_scope')->'owners'))), '[]'::jsonb)))::text) is distinct from c2_plan->>'target_reference_md5' then
raise exception 'C2 stale plan: the target reference rows changed since this plan was made; re-extract the target and re-plan' using errcode = 'P0001';
end if;
for pi in select * from jsonb_to_recordset(c2_plan#>'{prerequisites,identities}') as x(id uuid, email text) loop
tot_ids := tot_ids + 1;
if not exists (select 1 from fat.app_identities i where i.id = pi.id) then ins_ids := ins_ids + 1; end if;
perform fat.ensure_app_identity(pi.id, pi.email, 'legacy_supabase');
select * into ai from fat.app_identities i where i.id = pi.id;
if not found or ai.origin <> 'legacy_supabase' or ai.legacy_subject is distinct from pi.id or ai.status <> 'active'
or lower(ai.email) <> lower(pi.email) or not exists (select 1 from fat.profiles p where p.id = pi.id) then
raise exception 'C2 conflict: app identity % is not the preserved legacy_supabase identity this plan requires', pi.id using errcode = 'P0001';
end if;
end loop;
for pf in select * from jsonb_populate_recordset(null::fat.financial_years, c2_plan#>'{prerequisites,financial_years}') loop
tot_fys := tot_fys + 1;
insert into fat.financial_years (id, user_id, label, start_date, end_date, is_active)
values (pf.id, pf.user_id, pf.label, pf.start_date, pf.end_date, coalesce(pf.is_active, false)) on conflict do nothing;
get diagnostics n = row_count; ins_fys := ins_fys + n;
select * into ef from fat.financial_years f where f.id = pf.id;
if not found or (ef.user_id, ef.label, ef.start_date, ef.end_date) is distinct from (pf.user_id, pf.label, pf.start_date, pf.end_date) then
raise exception 'C2 conflict: financial year % differs from the source FY (or its owner/label is held by another FY)', pf.id using errcode = 'P0001';
end if;
end loop;
insert into fat_migrations.data_loads (change_id, kind, checksum) values (c2_plan->>'change_id', 'migration_batch', 'sha256:' || c2_plan_sha)
on conflict (change_id) do nothing;
get diagnostics nd = row_count;
if not exists (select 1 from fat_migrations.data_loads d where d.change_id = c2_plan->>'change_id' and d.kind = 'migration_batch' and d.checksum = 'sha256:' || c2_plan_sha) then
raise exception 'C2 conflict: data load % is recorded with a different plan checksum', c2_plan->>'change_id' using errcode = 'P0001';
end if;
insert into fat.migration_batches (batch_key, step, environment, tool, tool_version, source_checksum, status, completed_at, report, notes)
values (k, 'C2', c2_plan#>>'{batch,environment}', c2_plan#>>'{batch,report,tool,name}', c2_plan#>>'{batch,report,tool,version}',
c2_plan#>>'{batch,source_checksum}', 'completed', now(), c2_plan#>'{batch,report}',
'C2/C3 cross-database transform-copy (WORK-255; C2 WORK-190, C3 WORK-191); change=' || (c2_plan->>'change_id') || '; evidence_class=' || (c2_plan#>>'{batch,report,evidence_class}'))
on conflict (batch_key) do nothing;
get diagnostics nb = row_count;
select mb.id into b from fat.migration_batches mb
where mb.batch_key = k and mb.step = 'C2' and mb.environment = c2_plan#>>'{batch,environment}'
and mb.tool = c2_plan#>>'{batch,report,tool,name}' and mb.tool_version = c2_plan#>>'{batch,report,tool,version}'
and mb.source_checksum = c2_plan#>>'{batch,source_checksum}' and mb.status = 'completed' and mb.report = c2_plan#>'{batch,report}';
if b is null then
raise exception 'C2 conflict: batch % exists with a different definition, status or report', k using errcode = 'P0001';
end if;
for rc in select * from jsonb_populate_recordset(null::fat.operational_claims, c2_plan->'claims') loop
rc.migration_batch_id := b;
insert into fat.operational_claims (id, owner_id, claim_type, claim_date, station_id_snapshot, station_name_snapshot, source_calculation_mode, status, generated_at, notes, claim_number, financial_year_id, prototype_claim_group_id, prototype_source, prototype_row_id, migration_batch_id)
values (rc.id, rc.owner_id, rc.claim_type, rc.claim_date, rc.station_id_snapshot, rc.station_name_snapshot, rc.source_calculation_mode, rc.status, rc.generated_at, rc.notes, rc.claim_number, rc.financial_year_id, rc.prototype_claim_group_id, rc.prototype_source, rc.prototype_row_id, rc.migration_batch_id) on conflict do nothing;
get diagnostics n = row_count; ins_claims := ins_claims + n; tot_claims := tot_claims + 1;
select * into ec from fat.operational_claims where id = rc.id;
if not found or (ec.owner_id, ec.claim_type, ec.claim_date, ec.station_id_snapshot, ec.station_name_snapshot, ec.source_calculation_mode, ec.status, ec.generated_at, ec.notes, ec.claim_number, ec.financial_year_id, ec.prototype_claim_group_id, ec.prototype_source, ec.prototype_row_id, ec.parent_claim_id, ec.copy_source_owner_id) is distinct from (rc.owner_id, rc.claim_type, rc.claim_date, rc.station_id_snapshot, rc.station_name_snapshot, rc.source_calculation_mode, rc.status, rc.generated_at, rc.notes, rc.claim_number, rc.financial_year_id, rc.prototype_claim_group_id, rc.prototype_source, rc.prototype_row_id, rc.parent_claim_id, rc.copy_source_owner_id) then
raise exception 'C2 conflict: operational_claims % differs from the planned canonical row (or its lineage is held by another row)', rc.id using errcode = 'P0001';
end if;
end loop;
for r_recall_details in select * from jsonb_populate_recordset(null::fat.recall_details, c2_plan->'details'->'recall_details') loop
insert into fat.recall_details (claim_id, recall_station_id, recall_start_at, recall_end_at, travel_distance_km, travel_source, meal_break_taken, recall_duty, recall_travel_minutes, recall_travel_sunday_or_ph) values (r_recall_details.claim_id, r_recall_details.recall_station_id, r_recall_details.recall_start_at, r_recall_details.recall_end_at, r_recall_details.travel_distance_km, r_recall_details.travel_source, r_recall_details.meal_break_taken, r_recall_details.recall_duty, r_recall_details.recall_travel_minutes, r_recall_details.recall_travel_sunday_or_ph) on conflict do nothing;
get diagnostics n = row_count; ins_details := ins_details + n; tot_details := tot_details + 1;
select * into e_recall_details from fat.recall_details where claim_id = r_recall_details.claim_id;
if not found or e_recall_details is distinct from r_recall_details then
raise exception 'C2 conflict: fat.recall_details row for claim % differs from the planned canonical row', r_recall_details.claim_id using errcode = 'P0001';
end if;
end loop;
for r_retain_details in select * from jsonb_populate_recordset(null::fat.retain_details, c2_plan->'details'->'retain_details') loop
insert into fat.retain_details (claim_id, retain_start_at, retain_end_at, meal_break_taken, retain_shift, night_shift_interrupted, retain_travel_home_minutes) values (r_retain_details.claim_id, r_retain_details.retain_start_at, r_retain_details.retain_end_at, r_retain_details.meal_break_taken, r_retain_details.retain_shift, r_retain_details.night_shift_interrupted, r_retain_details.retain_travel_home_minutes) on conflict do nothing;
get diagnostics n = row_count; ins_details := ins_details + n; tot_details := tot_details + 1;
select * into e_retain_details from fat.retain_details where claim_id = r_retain_details.claim_id;
if not found or e_retain_details is distinct from r_retain_details then
raise exception 'C2 conflict: fat.retain_details row for claim % differs from the planned canonical row', r_retain_details.claim_id using errcode = 'P0001';
end if;
end loop;
for r_standby_details in select * from jsonb_populate_recordset(null::fat.standby_details, c2_plan->'details'->'standby_details') loop
insert into fat.standby_details (claim_id, standby_station_id, standby_start_at, standby_end_at, matrix_distance_km, matrix_hours, matrix_version, home_to_rostered_km, home_to_target_km) values (r_standby_details.claim_id, r_standby_details.standby_station_id, r_standby_details.standby_start_at, r_standby_details.standby_end_at, r_standby_details.matrix_distance_km, r_standby_details.matrix_hours, r_standby_details.matrix_version, r_standby_details.home_to_rostered_km, r_standby_details.home_to_target_km) on conflict do nothing;
get diagnostics n = row_count; ins_details := ins_details + n; tot_details := tot_details + 1;
select * into e_standby_details from fat.standby_details where claim_id = r_standby_details.claim_id;
if not found or e_standby_details is distinct from r_standby_details then
raise exception 'C2 conflict: fat.standby_details row for claim % differs from the planned canonical row', r_standby_details.claim_id using errcode = 'P0001';
end if;
end loop;
for r_muster_dismiss_details in select * from jsonb_populate_recordset(null::fat.muster_dismiss_details, c2_plan->'details'->'muster_dismiss_details') loop
insert into fat.muster_dismiss_details (claim_id, md_station_id, md_event_at, matrix_distance_km, matrix_hours, matrix_version, home_to_rostered_km, home_to_target_km) values (r_muster_dismiss_details.claim_id, r_muster_dismiss_details.md_station_id, r_muster_dismiss_details.md_event_at, r_muster_dismiss_details.matrix_distance_km, r_muster_dismiss_details.matrix_hours, r_muster_dismiss_details.matrix_version, r_muster_dismiss_details.home_to_rostered_km, r_muster_dismiss_details.home_to_target_km) on conflict do nothing;
get diagnostics n = row_count; ins_details := ins_details + n; tot_details := tot_details + 1;
select * into e_muster_dismiss_details from fat.muster_dismiss_details where claim_id = r_muster_dismiss_details.claim_id;
if not found or e_muster_dismiss_details is distinct from r_muster_dismiss_details then
raise exception 'C2 conflict: fat.muster_dismiss_details row for claim % differs from the planned canonical row', r_muster_dismiss_details.claim_id using errcode = 'P0001';
end if;
end loop;
for r_spoilt_meal_details in select * from jsonb_populate_recordset(null::fat.spoilt_meal_details, c2_plan->'details'->'spoilt_meal_details') loop
insert into fat.spoilt_meal_details (claim_id, meal_provisioned_at, spoilt_reason, meal_interrupted_at, emergency_response, emergency_call_ref) values (r_spoilt_meal_details.claim_id, r_spoilt_meal_details.meal_provisioned_at, r_spoilt_meal_details.spoilt_reason, r_spoilt_meal_details.meal_interrupted_at, r_spoilt_meal_details.emergency_response, r_spoilt_meal_details.emergency_call_ref) on conflict do nothing;
get diagnostics n = row_count; ins_details := ins_details + n; tot_details := tot_details + 1;
select * into e_spoilt_meal_details from fat.spoilt_meal_details where claim_id = r_spoilt_meal_details.claim_id;
if not found or e_spoilt_meal_details is distinct from r_spoilt_meal_details then
raise exception 'C2 conflict: fat.spoilt_meal_details row for claim % differs from the planned canonical row', r_spoilt_meal_details.claim_id using errcode = 'P0001';
end if;
end loop;
for r_delayed_meal_details in select * from jsonb_populate_recordset(null::fat.delayed_meal_details, c2_plan->'details'->'delayed_meal_details') loop
insert into fat.delayed_meal_details (claim_id, meal_window_start_at, meal_window_end_at, actual_meal_at, delay_notice_2h, delay_cause, duty_start_at, duty_end_at) values (r_delayed_meal_details.claim_id, r_delayed_meal_details.meal_window_start_at, r_delayed_meal_details.meal_window_end_at, r_delayed_meal_details.actual_meal_at, r_delayed_meal_details.delay_notice_2h, r_delayed_meal_details.delay_cause, r_delayed_meal_details.duty_start_at, r_delayed_meal_details.duty_end_at) on conflict do nothing;
get diagnostics n = row_count; ins_details := ins_details + n; tot_details := tot_details + 1;
select * into e_delayed_meal_details from fat.delayed_meal_details where claim_id = r_delayed_meal_details.claim_id;
if not found or e_delayed_meal_details is distinct from r_delayed_meal_details then
raise exception 'C2 conflict: fat.delayed_meal_details row for claim % differs from the planned canonical row', r_delayed_meal_details.claim_id using errcode = 'P0001';
end if;
end loop;
for re in select * from jsonb_populate_recordset(null::fat.claim_entitlements, c2_plan->'entitlements') loop
re.payment_status := case re.payment_method when 'payslip' then 'pending' when 'petty_cash' then 'outstanding' end;
insert into fat.claim_entitlements (id, claim_id, owner_id, entitlement_type, unit, generated_amount, generated_hours, rule_id, rule_version, rule_explanation, formula_explanation, rate_id, rate_version_id, rate_snapshot, payment_method, payment_status, generated_at, prototype_source, prototype_row_id, prototype_component, manual_override, migration_batch_id)
values (re.id, re.claim_id, re.owner_id, re.entitlement_type, re.unit, re.generated_amount, re.generated_hours, re.rule_id, re.rule_version, re.rule_explanation, re.formula_explanation, re.rate_id, re.rate_version_id, re.rate_snapshot, re.payment_method, re.payment_status, re.generated_at, re.prototype_source, re.prototype_row_id, re.prototype_component, false, b) on conflict do nothing;
get diagnostics n = row_count; ins_ents := ins_ents + n; tot_ents := tot_ents + 1;
if n = 1 and re.edited_amount is not null then
update fat.claim_entitlements set edited_amount = re.edited_amount, edited_note = re.edited_note, edited_source = re.edited_source
where id = re.id;
ins_adj := ins_adj + 1;
end if;
select * into ee from fat.claim_entitlements where id = re.id;
if not found or (ee.claim_id, ee.owner_id, ee.entitlement_type, ee.unit, ee.generated_amount, ee.generated_hours, ee.rule_id, ee.rule_version, ee.rule_explanation, ee.formula_explanation, ee.rate_id, ee.rate_version_id, ee.rate_snapshot, ee.payment_method, ee.generated_at, ee.prototype_source, ee.prototype_row_id, ee.prototype_component, ee.edited_amount, ee.edited_hours, ee.edited_note, ee.edited_source) is distinct from (re.claim_id, re.owner_id, re.entitlement_type, re.unit, re.generated_amount, re.generated_hours, re.rule_id, re.rule_version, re.rule_explanation, re.formula_explanation, re.rate_id, re.rate_version_id, re.rate_snapshot, re.payment_method, re.generated_at, re.prototype_source, re.prototype_row_id, re.prototype_component, re.edited_amount, re.edited_hours, re.edited_note, re.edited_source) then
raise exception 'C2 conflict: claim_entitlements % differs from the planned preserved entitlement', re.id using errcode = 'P0001';
end if;
end loop;
for rp in select * from jsonb_populate_recordset(null::fat.payment_records, c2_plan->'payment_records') loop
insert into fat.payment_records (id, owner_id, stream, record_date, reference, gross_amount, raw_payload, source, migration_source_key, migration_batch_id)
values (rp.id, rp.owner_id, rp.stream, rp.record_date, rp.reference, rp.gross_amount, rp.raw_payload, rp.source, rp.migration_source_key, b) on conflict do nothing;
get diagnostics n = row_count; ins_pay := ins_pay + n; tot_pay := tot_pay + 1;
if n = 1 then new_recs := new_recs || rp.id; end if;
select * into ep from fat.payment_records where id = rp.id;
if not found or (ep.owner_id, ep.stream, ep.record_date, ep.reference, ep.gross_amount, ep.raw_payload, ep.source, ep.migration_source_key) is distinct from (rp.owner_id, rp.stream, rp.record_date, rp.reference, rp.gross_amount, rp.raw_payload, rp.source, rp.migration_source_key) then
raise exception 'C2 conflict: payment_records % differs from the planned migrated payment record (or its migration_source_key is held by another row)', rp.id using errcode = 'P0001';
end if;
end loop;
for lk in select * from jsonb_to_recordset(c2_plan->'payment_links') as x(entitlement_id uuid, payment_record_id uuid, allocated_amount numeric, link_kind text, note text, actor_id uuid) loop
tot_links := tot_links + 1;
select * into elk from fat.entitlement_payment_links l
where l.entitlement_id = lk.entitlement_id and l.payment_record_id = lk.payment_record_id and l.link_kind = lk.link_kind;
if not found then
if not (lk.payment_record_id = any(new_recs)) then
raise exception 'C2 conflict: planned payment link % -> % is missing although its payment record already existed; it is not re-created', lk.entitlement_id, lk.payment_record_id using errcode = 'P0001';
end if;
perform fat.link_entitlement_payment(lk.entitlement_id, lk.payment_record_id, lk.allocated_amount, lk.link_kind, lk.actor_id, lk.note, true);
ins_links := ins_links + 1;
select * into elk from fat.entitlement_payment_links l
where l.entitlement_id = lk.entitlement_id and l.payment_record_id = lk.payment_record_id and l.link_kind = lk.link_kind;
end if;
if elk.allocated_amount is distinct from lk.allocated_amount or elk.note is distinct from lk.note then
raise exception 'C2 conflict: payment link % -> % differs from the planned allocation', lk.entitlement_id, lk.payment_record_id using errcode = 'P0001';
end if;
select count(*) into n from fat.reconciliation_audit a
where a.entitlement_id = lk.entitlement_id and a.action = 'link_payment' and a.reason = lk.note and a.actor_id = lk.actor_id and a.automated;
if n <> 1 then
raise exception 'C2 conflict: payment link % -> % has % link_payment audit row(s), expected exactly 1', lk.entitlement_id, lk.payment_record_id, n using errcode = 'P0001';
end if;
end loop;
select count(*) into n from fat.entitlement_payment_links l
where l.entitlement_id in (select (x->>'id')::uuid from jsonb_array_elements(c2_plan->'entitlements') x)
and not exists (select 1 from jsonb_array_elements(c2_plan->'payment_links') y
where (y->>'entitlement_id')::uuid = l.entitlement_id and (y->>'payment_record_id')::uuid = l.payment_record_id and y->>'link_kind' = l.link_kind);
if n > 0 then raise exception 'C2 conflict: % payment link(s) on migrated entitlements are not in the plan', n using errcode = 'P0001'; end if;
for ps in select * from jsonb_to_recordset(c2_plan->'entitlements') as x(id uuid, payment_status text) loop
select e.payment_status into cur_status from fat.claim_entitlements e where e.id = ps.id;
if cur_status is distinct from ps.payment_status then
raise exception 'C2 conflict: claim_entitlements % payment_status % differs from the planned %', ps.id, cur_status, ps.payment_status using errcode = 'P0001';
end if;
select r.changed into ch from fat._reconc_recompute(ps.id) r;
if ch then raise exception 'C3 postcondition: claim_entitlements % payment_status is not the canonical recompute derivation', ps.id using errcode = 'P0001'; end if;
end loop;
for rl in select * from jsonb_populate_recordset(null::fat.migration_source_rows, c2_plan->'ledger') loop
insert into fat.migration_source_rows (id, owner_id, source_table, source_row_id, source_claim_group_id, source_claim_type, source_checksum, source_snapshot, disposition, target_claim_id, exclusion_code, exclusion_reason, batch_id)
values (rl.id, rl.owner_id, rl.source_table, rl.source_row_id, rl.source_claim_group_id, rl.source_claim_type, rl.source_checksum, rl.source_snapshot, rl.disposition, rl.target_claim_id, rl.exclusion_code, rl.exclusion_reason, b) on conflict do nothing;
get diagnostics n = row_count; ins_ledger := ins_ledger + n; tot_ledger := tot_ledger + 1;
select * into el from fat.migration_source_rows where id = rl.id;
if not found or (el.owner_id, el.source_table, el.source_row_id, el.source_claim_group_id, el.source_claim_type, el.source_checksum, el.source_snapshot, el.disposition, el.target_claim_id, el.exclusion_code, el.exclusion_reason) is distinct from (rl.owner_id, rl.source_table, rl.source_row_id, rl.source_claim_group_id, rl.source_claim_type, rl.source_checksum, rl.source_snapshot, rl.disposition, rl.target_claim_id, rl.exclusion_code, rl.exclusion_reason) then
raise exception 'C2 conflict: migration_source_rows % (% %) differs from the planned disposition', rl.id, rl.source_table, rl.source_row_id using errcode = 'P0001';
end if;
end loop;
select count(*) into n from fat.operational_claims oc
where oc.migration_batch_id = b and oc.id not in (select (x->>'id')::uuid from jsonb_array_elements(c2_plan->'claims') x);
if n > 0 then raise exception 'C2 postcondition: % claim(s) tagged to batch % are not in the plan', n, k using errcode = 'P0001'; end if;
select count(*) into n from fat.claim_entitlements ce
where ce.migration_batch_id = b and ce.id not in (select (x->>'id')::uuid from jsonb_array_elements(c2_plan->'entitlements') x);
if n > 0 then raise exception 'C2 postcondition: % entitlement(s) tagged to batch % are not in the plan', n, k using errcode = 'P0001'; end if;
select count(*) into n from fat.migration_source_rows ms
where ms.batch_id = b and ms.id not in (select (x->>'id')::uuid from jsonb_array_elements(c2_plan->'ledger') x);
if n > 0 then raise exception 'C2 postcondition: % ledger row(s) of batch % are not in the plan', n, k using errcode = 'P0001'; end if;
select count(*) into n from fat.payment_records pr
where pr.migration_batch_id = b and pr.id not in (select (x->>'id')::uuid from jsonb_array_elements(c2_plan->'payment_records') x);
if n > 0 then raise exception 'C2 postcondition: % payment record(s) tagged to batch % are not in the plan', n, k using errcode = 'P0001'; end if;
select count(*) into n from jsonb_array_elements(c2_plan->'claims') x, lateral (select
(select count(*) from fat.recall_details dd where dd.claim_id = (x->>'id')::uuid) n_rc,
(select count(*) from fat.retain_details dd where dd.claim_id = (x->>'id')::uuid) n_rt,
(select count(*) from fat.standby_details dd where dd.claim_id = (x->>'id')::uuid) n_sb,
(select count(*) from fat.muster_dismiss_details dd where dd.claim_id = (x->>'id')::uuid) n_md,
(select count(*) from fat.spoilt_meal_details dd where dd.claim_id = (x->>'id')::uuid) n_sm,
(select count(*) from fat.delayed_meal_details dd where dd.claim_id = (x->>'id')::uuid) n_dm) d
where d.n_rc + d.n_rt + d.n_sb + d.n_md + d.n_sm + d.n_dm <> 1
or (case x->>'claim_type' when 'RC' then d.n_rc when 'RT' then d.n_rt when 'SB' then d.n_sb when 'MD' then d.n_md when 'SM' then d.n_sm else d.n_dm end) <> 1;
if n > 0 then raise exception 'C2 postcondition (gate 3): % claim(s) without exactly one correct detail row', n using errcode = 'P0001'; end if;
select count(*) into n from jsonb_array_elements(c2_plan->'ledger') x
where x->>'disposition' <> 'claim'
and (select count(*) from fat.claim_entitlements e where e.prototype_source = x->>'source_table' and e.prototype_row_id = (x->>'source_row_id')::uuid)
<> (select count(*) from jsonb_array_elements(c2_plan->'entitlements') y where y->>'prototype_source' = x->>'source_table' and y->>'prototype_row_id' = x->>'source_row_id');
if n > 0 then raise exception 'C2 postcondition (gate 4): % child row(s) do not map to exactly their planned entitlements', n using errcode = 'P0001'; end if;
select count(*) into n from jsonb_array_elements(c2_plan->'ledger') x
where x->>'disposition' = 'excluded' and x->>'exclusion_code' not in ('G12_FAKE_RECALL_EXCESS_TRAVEL', 'EMPTY_CLAIM_GROUP');
if n > 0 then raise exception 'C2 postcondition (gate 4): unapproved exclusion code' using errcode = 'P0001'; end if;
select count(*) into n from jsonb_array_elements(c2_plan->'ledger') x
where x->>'exclusion_code' in ('EMPTY_CLAIM_GROUP')
and (x->>'target_claim_id' is not null or x->>'source_table' <> 'claim_groups'
or exists (select 1 from fat.operational_claims oc where oc.prototype_claim_group_id = (x->>'source_row_id')::uuid));
if n > 0 then raise exception 'C2 postcondition (gate 1): % EMPTY_CLAIM_GROUP row(s) carry or produced a claim', n using errcode = 'P0001'; end if;
select count(*) into n from jsonb_array_elements(c2_plan->'entitlements') x
where x->>'edited_source' is not null
and (select count(*) from fat.entitlement_overrides o where o.entitlement_id = (x->>'id')::uuid and o.field = 'edited_amount' and o.source_ref = x->>'edited_source') <> 1;
if n > 0 then raise exception 'C2 postcondition: % adjustment(s) without exactly one audited override', n using errcode = 'P0001'; end if;
c2_result := jsonb_build_object(
'batch_key', k, 'batch_id', b, 'batch_inserted', nb, 'change_id', c2_plan->>'change_id', 'data_load_inserted', nd,
'identities', jsonb_build_object('planned', tot_ids, 'inserted', ins_ids, 'verified_existing', tot_ids - ins_ids),
'financial_years', jsonb_build_object('planned', tot_fys, 'inserted', ins_fys, 'verified_existing', tot_fys - ins_fys),
'claims', jsonb_build_object('planned', tot_claims, 'inserted', ins_claims, 'verified_existing', tot_claims - ins_claims),
'details', jsonb_build_object('planned', tot_details, 'inserted', ins_details, 'verified_existing', tot_details - ins_details),
'entitlements', jsonb_build_object('planned', tot_ents, 'inserted', ins_ents, 'verified_existing', tot_ents - ins_ents, 'adjustments_applied', ins_adj),
'ledger', jsonb_build_object('planned', tot_ledger, 'inserted', ins_ledger, 'verified_existing', tot_ledger - ins_ledger),
'payment_records', jsonb_build_object('planned', tot_pay, 'inserted', ins_pay, 'verified_existing', tot_pay - ins_pay),
'payment_links', jsonb_build_object('planned', tot_links, 'linked', ins_links, 'verified_existing', tot_links - ins_links));
end c2_apply;
  -- plan_sha256 proves the SQL that ran carried exactly the reviewed plan (compare with plan.sha256).
  c2_result := c2_result || jsonb_build_object('plan_sha256', c2_plan_sha);
  perform set_config('fat_c2.apply_result', c2_result::text, true);
end
$c2apply$;
select nullif(current_setting('fat_c2.apply_result', true), '')::jsonb as apply_result;
